// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address payer, uint256 amount) public {
        vm.assume(payer != address(0));
        amount = bound(amount, 1, 1 ether);

        vm.deal(payer, amount);
        bool ok;
        vm.prank(payer);
        (bool success, ) = address(c).call{value: amount}("");
        ok = success;

        assertTrue(ok && c.depositsCount() == 1);
    }
}
